created=[]
def parts(*marks):return [(f'component-{i}',f'Component {i}',m) for i,m in enumerate(marks,1)]
def rs(label,marks,labels=None):return response(1,label,[(f'component-{i}',labels[i-1] if labels else f'Component {i}',m) for i,m in enumerate(marks,1)])
def rows(labels,marks=(2,3)):return [response(i,label,[('explain','Explanation',marks[0]),('develop','Development',marks[1])]) for i,label in enumerate(labels,1)]
def add(section,q,suffix,prompt,total,topic,concept,page,support,requirement,responses,guidance=None,extra=None,marknote=None):
 part=''.join(f'({v.upper() if section==3 and i==0 else v})' for i,v in enumerate(suffix.split('-'))) if suffix else ''
 tariff=5 if section==1 else {1:7,2:8,3:8,4:9,5:10,6:11,7:12}[q]
 c=dict(id=f'bus-2016-hl-s{section}-q{q}{suffix}',year=year,level='higher',section=str(section),paperFileid='LC033ALP000EV',paperPages=[page],sourceLabel='QUESTION PAPER',sourceTitle=f'2016 Business · Section {section} Question {q}',questionRef=f'2016 HL Section {section} Q{q}{part}',questionText=prompt,totalMarks=total,topicId=topic,conceptId=concept,rubric=dict(system='business',taskRequirements=[requirement],guidance=guidance or [],responses=responses,schemeFileid='LC033ALP000EV',schemePages=[tariff]+support,markingGuideNote=marknote or notes))
 if extra:c['additionalTopicIds']=extra
 assert sum(a['maxMarks'] for r in responses for a in r['allocations'])==total,c['id']
 created.append(c)
 return c
def binary(c):
 for r in c['rubric']['responses']:
  for a in r['allocations']:a['permittedMarks']=[0,a['maxMarks']]
 return c
def cumulative(q,prompt,topic,concept,page,support,answers,extra=None):
 c=add(1,q,'',prompt,10,topic,concept,page,support,'Complete all five answers. The published cumulative sequence is 3 + 3 + 2 + 1 + 1.',[rs('Correct answers',(10,),['Total from the published sequence'])],[answers,'For 0, 1, 2, 3, 4 or 5 correct answers, record 0, 3, 6, 8, 9 or 10 marks. The larger allowances are not tied to particular printed rows.'],extra=extra,marknote='Use the official answer key and cumulative sequence. Each correct answer counts once.')
 c['rubric']['responses'][0]['allocations'][0]['permittedMarks']=[0,3,6,8,9,10]

